// Collect all matching messages across paginated responses and count per user
const keywords = ['gong.io', 'pidgeonhead', 'research call', 'session'];
const counts = {};

for (const item of $input.all()) {
  const body = item.json;
  const messages = Array.isArray(body.messages) ? body.messages : [];
  for (const msg of messages) {
    // skip system/join-leave style subtypes, keep normal + broadcasts + bot messages
    if (msg.subtype && msg.subtype !== 'thread_broadcast' && msg.subtype !== 'bot_message') continue;
    const text = (msg.text || '').toLowerCase();
    if (!keywords.some(k => text.includes(k))) continue;
    const user = msg.user || msg.bot_id || 'unknown';
    counts[user] = (counts[user] || 0) + 1;
  }
}

const total = Object.values(counts).reduce((a, b) => a + b, 0);

// One item per distinct user; totalMatched carried on each for percentage calc
return Object.entries(counts).map(([userId, count]) => ({
  json: { userId, count, totalMatched: total }
}));

// Combine users.info responses with the counts from the Filter node.
// The Resolve User Name node preserves item pairing, so we read counts from
// the paired 'Filter & Count Per User' item by index.
const results = [];

const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const info = items[i].json; // users.info response
  const source = $('Filter & Count Per User').all()[i].json;
  const userObj = info && info.user ? info.user : null;
  const profile = userObj && userObj.profile ? userObj.profile : {};
  const name = (profile.real_name || profile.display_name || (userObj && userObj.name) || source.userId);
  const total = source.totalMatched || 0;
  const pct = total > 0 ? (source.count / total) * 100 : 0;
  results.push({
    userId: source.userId,
    name,
    count: source.count,
    percentage: Math.round(pct * 10) / 10
  });
}

// Sort descending by count
results.sort((a, b) => b.count - a.count);

// Render a markdown table summary
const header = '| User | Messages | % of total |\n|---|---|---|';
const bodyRows = results.map(r => `| ${r.name} | ${r.count} | ${r.percentage}% |`).join('\n');
const table = header + '\n' + bodyRows;

const totalMatched = results.reduce((a, r) => a + r.count, 0);

return [
  { json: { summaryTable: table, totalMatched, distinctUsers: results.length, rows: results } }
];
